∀ {F G : D0.Foundation.EmpiricalTheoryFactorization.FutureExecution}
  (I : D0.Foundation.TheoryTransfer.Interpretation F G) (s : F.State) (w : List F.Action) (t : F.Test),
  I.commonExecution.profile (I.stateMap s) w t = I.outcomeMap (F.profile s w t)

∀ {F G : D0.Foundation.EmpiricalTheoryFactorization.FutureExecution}
  (I : D0.Foundation.TheoryTransfer.Interpretation F G) (s t : F.State),
  I.commonExecution.profile (I.stateMap s) = I.commonExecution.profile (I.stateMap t) ↔ F.profile s = F.profile t

∀ {F G : D0.Foundation.EmpiricalTheoryFactorization.FutureExecution}
  (I : D0.Foundation.TheoryTransfer.Interpretation F G) (w : List F.Action) (s : G.State),
  I.commonExecution.run w s = G.run (I.compile w) s

∀ {F G H : D0.Foundation.EmpiricalTheoryFactorization.FutureExecution}
  (I : D0.Foundation.TheoryTransfer.Interpretation F G) (J : D0.Foundation.TheoryTransfer.Interpretation G H),
  Function.Injective (J.outcomeMap ∘ I.outcomeMap)

∀ {F G H : D0.Foundation.EmpiricalTheoryFactorization.FutureExecution}
  (I : D0.Foundation.TheoryTransfer.Interpretation F G) (J : D0.Foundation.TheoryTransfer.Interpretation G H)
  (w : List F.Action), (I.comp J).compile w = J.compile (I.compile w)

∀ {F G : D0.Foundation.EmpiricalTheoryFactorization.FutureExecution}
  (I : D0.Foundation.TheoryTransfer.Interpretation F G) (a : F.Action) (w : List F.Action),
  I.compile (a :: w) = I.actionWord a ++ I.compile w

∀ {F G : D0.Foundation.EmpiricalTheoryFactorization.FutureExecution}
  (I : D0.Foundation.TheoryTransfer.Interpretation F G) (u v : List F.Action),
  I.compile (u ++ v) = I.compile u ++ I.compile v

∀ {F G : D0.Foundation.EmpiricalTheoryFactorization.FutureExecution}
  (I : D0.Foundation.TheoryTransfer.Interpretation F G) (a : F.Action) (q : F.FutureClass),
  I.futureMap (F.quotientStep a q) = I.commonExecution.quotientStep a (I.futureMap q)

∀ {F G : D0.Foundation.EmpiricalTheoryFactorization.FutureExecution}
  (I : D0.Foundation.TheoryTransfer.Interpretation F G),
  (Function.Injective fun q => ⟨I.futureMap q, ⋯⟩) ∧ Function.Surjective fun q => ⟨I.futureMap q, ⋯⟩

∀ {F G : D0.Foundation.EmpiricalTheoryFactorization.FutureExecution}
  (I : D0.Foundation.TheoryTransfer.Interpretation F G) (motive : I.EmpiricalImage → Prop) (h : I.EmpiricalImage),
  (∀ (q : I.commonExecution.FutureClass) (p : F.FutureClass) (hp : I.futureMap p = q), motive ⟨q, ⋯⟩) → motive h

∀ {F G : D0.Foundation.EmpiricalTheoryFactorization.FutureExecution}
  (I : D0.Foundation.TheoryTransfer.Interpretation F G) (a : F.Action) (q : F.FutureClass),
  I.imageEquiv (F.quotientStep a q) = I.imageStep a (I.imageEquiv q)

∀ {F G : D0.Foundation.EmpiricalTheoryFactorization.FutureExecution}
  (I : D0.Foundation.TheoryTransfer.Interpretation F G) (a : F.Action) (q : I.EmpiricalImage),
  ∃ p, I.futureMap p = I.commonExecution.quotientStep a ↑q

∀ {F G : D0.Foundation.EmpiricalTheoryFactorization.FutureExecution} {stateMap : F.State → G.State}
  {actionWord : F.Action → List G.Action} {testMap : F.Test → G.Test} {outcomeMap : F.Outcome → G.Outcome}
  {outcome_injective : Function.Injective outcomeMap}
  {step_commutes : ∀ (a : F.Action) (s : F.State), stateMap (F.step a s) = G.run (actionWord a) (stateMap s)}
  {observe_commutes : ∀ (s : F.State) (t : F.Test), G.observe (stateMap s) (testMap t) = outcomeMap (F.observe s t)}
  {stateMap_1 : F.State → G.State} {actionWord_1 : F.Action → List G.Action} {testMap_1 : F.Test → G.Test}
  {outcomeMap_1 : F.Outcome → G.Outcome} {outcome_injective_1 : Function.Injective outcomeMap_1}
  {step_commutes_1 : ∀ (a : F.Action) (s : F.State), stateMap_1 (F.step a s) = G.run (actionWord_1 a) (stateMap_1 s)}
  {observe_commutes_1 :
    ∀ (s : F.State) (t : F.Test), G.observe (stateMap_1 s) (testMap_1 t) = outcomeMap_1 (F.observe s t)},
  { stateMap := stateMap, actionWord := actionWord, testMap := testMap, outcomeMap := outcomeMap,
        outcome_injective := outcome_injective, step_commutes := step_commutes, observe_commutes := observe_commutes } =
      { stateMap := stateMap_1, actionWord := actionWord_1, testMap := testMap_1, outcomeMap := outcomeMap_1,
        outcome_injective := outcome_injective_1, step_commutes := step_commutes_1,
        observe_commutes := observe_commutes_1 } →
    stateMap = stateMap_1 ∧ actionWord = actionWord_1 ∧ testMap = testMap_1 ∧ outcomeMap = outcomeMap_1

∀ {F G : D0.Foundation.EmpiricalTheoryFactorization.FutureExecution}
  (I : D0.Foundation.TheoryTransfer.Interpretation F G) {s t : F.State},
  G.profile (I.stateMap s) = G.profile (I.stateMap t) → F.profile s = F.profile t

∀ {F G : D0.Foundation.EmpiricalTheoryFactorization.FutureExecution}
  (self : D0.Foundation.TheoryTransfer.Interpretation F G) (s : F.State) (t : F.Test),
  G.observe (self.stateMap s) (self.testMap t) = self.outcomeMap (F.observe s t)

∀ {F G : D0.Foundation.EmpiricalTheoryFactorization.FutureExecution}
  (I : D0.Foundation.TheoryTransfer.Interpretation F G) (s : F.State) (w : List F.Action) (t : F.Test),
  G.profile (I.stateMap s) (I.compile w) (I.testMap t) = I.outcomeMap (F.profile s w t)

∀ {F G : D0.Foundation.EmpiricalTheoryFactorization.FutureExecution}
  (I : D0.Foundation.TheoryTransfer.Interpretation F G) (w : List F.Action) (s : F.State),
  I.stateMap (F.run w s) = G.run (I.compile w) (I.stateMap s)

∀ {F G : D0.Foundation.EmpiricalTheoryFactorization.FutureExecution}
  (self : D0.Foundation.TheoryTransfer.Interpretation F G) (a : F.Action) (s : F.State),
  self.stateMap (F.step a s) = G.run (self.actionWord a) (self.stateMap s)

∀ {F G : D0.Foundation.EmpiricalTheoryFactorization.FutureExecution}
  (I : D0.Foundation.TheoryTransfer.Interpretation F G) (H P : F.FutureClass → Prop),
  (∀ (q : F.FutureClass), H q → P q) → ∀ (q : I.EmpiricalImage), I.translate H q → I.translate P q

∀ {F G : D0.Foundation.EmpiricalTheoryFactorization.FutureExecution}
  (I : D0.Foundation.TheoryTransfer.Interpretation F G) (P : F.FutureClass → Prop) (q : I.EmpiricalImage),
  I.translate P q = P (I.imageEquiv.symm q)

∀ {F G : D0.Foundation.EmpiricalTheoryFactorization.FutureExecution}
  (I : D0.Foundation.TheoryTransfer.Interpretation F G) (P : F.FutureClass → Prop) (a : F.Action) (q : F.FutureClass),
  I.translate P (I.imageStep a (I.imageEquiv q)) ↔ P (F.quotientStep a q)

∀ {F G : D0.Foundation.EmpiricalTheoryFactorization.FutureExecution}
  (I : D0.Foundation.TheoryTransfer.Interpretation F G) (P : F.FutureClass → Prop) (q : F.FutureClass),
  I.translate P (I.imageEquiv q) ↔ P q

∀ {F G : D0.Foundation.EmpiricalTheoryFactorization.FutureExecution}
  (I : D0.Foundation.TheoryTransfer.Interpretation F G) (P : F.FutureClass → Prop) (q : F.FutureClass),
  I.translate P (I.imageEquiv q) = P q

∀ {F G : D0.Foundation.EmpiricalTheoryFactorization.FutureExecution}
  (I : D0.Foundation.TheoryTransfer.Interpretation F G) (P Q : F.FutureClass → Prop) (q : I.EmpiricalImage),
  I.translate (fun x => P x ∧ Q x) q ↔ I.translate P q ∧ I.translate Q q

∀ {F G : D0.Foundation.EmpiricalTheoryFactorization.FutureExecution}
  (I : D0.Foundation.TheoryTransfer.Interpretation F G) {ι : Type u_1} (P : ι → F.FutureClass → Prop)
  (q : I.EmpiricalImage), I.translate (fun x => ∀ (i : ι), P i x) q ↔ ∀ (i : ι), I.translate (P i) q

∀ {F G : D0.Foundation.EmpiricalTheoryFactorization.FutureExecution}
  (I : D0.Foundation.TheoryTransfer.Interpretation F G) (P Q : F.FutureClass → Prop) (q : I.EmpiricalImage),
  I.translate (fun x => P x → Q x) q ↔ I.translate P q → I.translate Q q

∀ {F G : D0.Foundation.EmpiricalTheoryFactorization.FutureExecution}
  (I : D0.Foundation.TheoryTransfer.Interpretation F G) (P : F.FutureClass → Prop) (q : I.EmpiricalImage),
  I.translate (fun x => ¬P x) q ↔ ¬I.translate P q

∀ {F G : D0.Foundation.EmpiricalTheoryFactorization.FutureExecution}
  {I : D0.Foundation.TheoryTransfer.Interpretation F G} {context : List G.Action → G.Test → List F.Action × F.Test}
  {readout : List G.Action → G.Test → F.Outcome → G.Outcome}
  {correct :
    ∀ (s : F.State) (w : List G.Action) (t : G.Test),
      G.profile (I.stateMap s) w t = readout w t (F.profile s (context w t).1 (context w t).2)}
  {context_1 : List G.Action → G.Test → List F.Action × F.Test}
  {readout_1 : List G.Action → G.Test → F.Outcome → G.Outcome}
  {correct_1 :
    ∀ (s : F.State) (w : List G.Action) (t : G.Test),
      G.profile (I.stateMap s) w t = readout_1 w t (F.profile s (context_1 w t).1 (context_1 w t).2)},
  { context := context, readout := readout, correct := correct } =
      { context := context_1, readout := readout_1, correct := correct_1 } →
    context = context_1 ∧ readout = readout_1

∀ {F G : D0.Foundation.EmpiricalTheoryFactorization.FutureExecution}
  {I : D0.Foundation.TheoryTransfer.Interpretation F G} (C : D0.Foundation.TheoryTransfer.NativeContextCoverage I)
  (s t : F.State), G.profile (I.stateMap s) = G.profile (I.stateMap t) ↔ F.profile s = F.profile t
